#!/usr/bin/env node
/**
 * NDC — Patch v2 « logo officiel + accueil mobile + page vide Google » (nov. 2026)
 * ------------------------------------------------------------------------------
 * Écrit pour le code en production (archive ndc-front du 13/11/2026).
 * À lancer sur le SERVEUR NEXT.JS, depuis le dossier du projet :
 *
 *   node ndc-patch-v2.mjs              → APERÇU : liste les modifications, n'écrit rien
 *   node ndc-patch-v2.mjs --apply      → applique (avec sauvegardes)
 *   node ndc-patch-v2.mjs --restore    → remet les fichiers d'avant le patch
 *
 * 1. Logo officiel (SVG) dans le header, le footer et les visuels de
 *    remplacement ; favicon carré construit sur les lettres officielles.
 * 2. Menu mobile réparé (il s'ouvrait vide sur téléphone).
 * 3. Accueil sur téléphone : hero (variante A), chiffres clés en 2 × 2,
 *    cartes data centers lisibles, engagements sur une colonne, raison d'être,
 *    bulle de l'assistant plus discrète (masquée pendant le défilement).
 * 4. Page vide dans Google : les pages WordPress techniques (« Nos data
 *    centers »…) redirigent vers la vraie page ; une page WP vide renvoie 404.
 * 5. SEO : logo carré pour Google, icône 192 px.
 *
 * Tout ou rien : si une modification obligatoire ne trouve pas son repère,
 * RIEN n'est écrit. Relançable sans risque. Ensuite : npm run build, puis
 * pm2 restart <app> --update-env. Node 18+, aucune dépendance.
 */

import { copyFileSync, existsSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

