const SLUG = 'app/[locale]/[slug]/page.tsx';
edit(SLUG, 'pages WP techniques → vraie page (308), page WP vide → 404', {
  done: (s) => s.includes('TECHNICAL_PAGES'),
  apply: (s) => {
    let out = once("import { notFound } from 'next/navigation';", "import { notFound, permanentRedirect } from 'next/navigation';")(s);
    if (out) out = once("import { alternatesFor } from '@/lib/seo';", "import { alternatesFor, localePath } from '@/lib/seo';")(out);
    if (out) out = once('export const revalidate = 300;', `export const revalidate = 300;

// Pages WordPress « techniques » : elles ne portent que les champs d'une page
// du site (titre seul, sans contenu). Servies telles quelles, elles donnaient
// une page vide que Google a indexée (« Nos data centers »). Leur adresse
// renvoie désormais vers la vraie page.
const TECHNICAL_PAGES: Record<string, string> = {
  accueil: '/', 'accueil-2': '/',
  'datacenters-2': '/datacenters', 'nos-data-centers': '/datacenters',
  'services-2': '/services', 'nos-services': '/services',
  'equipes-2': '/equipes', 'nos-equipes': '/equipes', 'notre-equipe': '/equipes',
  'groupe-2': '/groupe', 'contact-2': '/contact', 'documentation-2': '/documentation',
};

/** Page WordPress sans contenu ni image : rien à afficher (404, non indexée). */
function isEmptyPage(page: { content?: string | null; image?: unknown }): boolean {
  return !page.image && !stripHtml(page.content ?? '').trim();
}`)(out);
    if (out) out = once('  if (!page) return {};', "  if (!page || isEmptyPage(page)) return { robots: { index: false } };")(out);
    if (out) out = once('  setRequestLocale(params.locale);\n  const page = await getPage(params.slug, params.locale);\n  if (!page) notFound();',
      `  setRequestLocale(params.locale);
  const target = TECHNICAL_PAGES[params.slug];
  if (target) permanentRedirect(localePath(params.locale, target));
  const page = await getPage(params.slug, params.locale);
  if (!page || isEmptyPage(page)) notFound();`)(out);
    return out;
  },
});

