log('');
if (!changes.size) { log('✅ Patch déjà appliqué. Rien à faire.'); process.exit(0); }
for (const [file, c] of changes) log(`  ${c.created ? '+' : '~'} ${file} : ${c.notes.join(' ; ')}`);
for (const w of warnings) log(`  ⚠️  ${w}`);

if (!APPLY) { log('\nAPERÇU seulement. Pour appliquer : node ndc-patch-v2.mjs --apply'); process.exit(0); }

const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const manifest = { date: new Date().toISOString(), files: [] };
for (const [file, c] of changes) {
  if (c.created) manifest.files.push({ file, created: true });
  else { const backup = `${file}.bak-ndc-${stamp}`; copyFileSync(join(ROOT, file), join(ROOT, backup)); manifest.files.push({ file, backup }); }
}
for (const [file, c] of changes) writeFileSync(join(ROOT, file), c.after);
writeFileSync(MANIFEST, JSON.stringify(manifest, null, 2));

log(`\n✅ Patch appliqué. Sauvegardes : *.bak-ndc-${stamp} (annulation : node ndc-patch-v2.mjs --restore)`);
log('\nÉtapes suivantes :');
